// Edge case tests for the fix
const mri = require('../lib/index.js');
let pass = 0, fail = 0;

function check(name, actual, expected) {
  if (actual === expected) { pass++; }
  else { fail++; console.log(`FAIL ${name}: got ${JSON.stringify(actual)}, expected ${JSON.stringify(expected)}`); }
}

// Basic: no alias, no default, string option
check('no alias string opt', mri(['-s', '007'], { string: 's' }).s, '007');

// Alias with string option
check('alias + string opt', mri(['-a', '007'], { alias: { a: 'arg' }, string: 'a' }).a, '007');

// Default string (no alias)
check('default string no alias', mri([], { default: { x: '007' } }).x, '007');

// THE BUG: default string + alias
