  test("handles -- separator", () => {
    expect(mri(["--", "--not-a-flag"])).toEqual({ _: ["--not-a-flag"] });
  });

  test("coerces numbers by default", () => {
    expect(mri(["--count", "42"])).toEqual({ _: [], count: 42 });
    expect(typeof mri(["--count", "42"]).count).toBe("number");
