// Edge case tests for the fix
const mri = require('../lib/index.js');
let pass = 0, fail = 0;

function check(name, actual, expected) {
  if (actual === expected) { pass++; }
  else { fail++; console.log(`FAIL ${name}: got ${JSON.stringify(actual)}, expected ${JSON.stringify(expected)}`); }
}

// Basic: no alias, no default, string option
check('no alias string opt', mri(['-s', '007'], { string: 's' }).s, '007');

// Alias with string option
check('alias + string opt', mri(['-a', '007'], { alias: { a: 'arg' }, string: 'a' }).a, '007');

// Default string (no alias)
check('default string no alias', mri([], { default: { x: '007' } }).x, '007');

// THE BUG: default string + alias
const r = mri(['-a', '01'], { alias: { arg: 'a' }, default: { arg: '01' } });
check('default string + alias (a)', r.a, '01');
check('default string + alias (arg)', r.arg, '01');

// Default boolean + alias
const r2 = mri(['-b'], { alias: { flag: 'b' }, default: { flag: false } });
check('default bool + alias (b)', r2.b, true);  // -b overrides default

// Default number + alias
const r3 = mri(['-n', '42'], { alias: { num: 'n' }, default: { num: 10 } });
check('default number + alias (n)', r3.n, 42);
check('default number + alias (num)', r3.num, 42);

// No args, default should kick in
const r4 = mri([], { alias: { arg: 'a' }, default: { arg: 'hello' } });
check('no args default string (a)', r4.a, 'hello');
check('no args default string (arg)', r4.arg, 'hello');

// Multi-char alias
const r5 = mri(['-x', '001'], { alias: { x: ['xx', 'xxx'] }, default: { x: 'default' } });
check('multi alias string (x)', r5.x, '001');
check('multi alias string (xx)', r5.xx, '001');
check('multi alias string (xxx)', r5.xxx, '001');

console.log(`\nResults: ${pass} passed, ${fail} failed`);
if (fail > 0) process.exit(1);
